"""Responsabilidad Personal y Social EPJA Media N1 y N2, módulo 1: reconocer fortalezas y recursos personales y del contexto, valorarlos y proyectar el crecimiento personal (OAD-01 a OAD-04). Todo en papel; personajes y casos ficticios; sin preguntar por vivencias reales."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel y lápiz. Todo se resuelve con lo escrito en la ficha. Los personajes y los casos son inventados: no hace falta contar nada personal ni mostrar lo que escribas sobre ti."
build = make_build(MATERIALS)

O1 = "EPJA-RPSO-NM1y2-OAD-01"
O2 = "EPJA-RPSO-NM1y2-OAD-02"
O3 = "EPJA-RPSO-NM1y2-OAD-03"
O4 = "EPJA-RPSO-NM1y2-OAD-04"
PRIOR = ["Tengo experiencia de vida: he aprendido cosas en el trabajo, en la casa y en la comunidad.", "Puedo leer una ficha corta y responder por escrito o en voz alta."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    stmt, example, crit, evid, err, fb = op
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=(stmt, example, crit, evid, err, fb), reinforce=rf, extend=ex_)


